package org.genhttp.modules.compression

import org.genhttp.modules.compression.algorithms.BrotliAlgorithm
import org.genhttp.modules.compression.algorithms.GzipAlgorithm
import org.genhttp.modules.compression.algorithms.ZstdAlgorithm
import org.genhttp.modules.compression.providers.CompressionConcernBuilder

/**
 * Entry point to compress the responses generated by a server.
 */
public object CompressedContent {

    // region Builder

    /**
     * Creates an empty builder that can be configured by adding
     * compression algorithms.
     *
     * @return The newly created builder
     */
    public fun empty(): CompressionConcernBuilder = CompressionConcernBuilder()

    /**
     * Creates a pre-configured builder which already supports
     * Zstandard, Brotli and Gzip compression.
     *
     * @return The newly created builder
     */
    public fun default(): CompressionConcernBuilder = CompressionConcernBuilder()
        .add(BrotliAlgorithm())
        .add(GzipAlgorithm())
        .add(ZstdAlgorithm())

    // endregion

}
